-- Supabase / PostgreSQL
-- PERINGATAN: skrip ini mengganti public.outlets beserta seluruh datanya.
-- Sumber data: outlet/*.json
-- Nilai brand mengikuti BrandKey aplikasi: fore, kopken, tomoro, starbuck.

begin;

-- Tanpa CASCADE agar dependensi di luar tabel tidak ikut terhapus diam-diam.
drop table if exists public.outlets;

create table public.outlets (
    id bigint generated always as identity primary key,
    brand text not null,
    name text not null,
    city_or_regency text,
    city text,
    regency text,
    area text,
    address text,
    opening_hours_displayed text,
    opening_hours text,
    source text,
    source_url text,
    verification_status text,
    google_maps_place_id text,
    place_id text,
    rating numeric(2, 1),
    review_count integer,
    phone text,
    additional_source text,
    google_maps_source text,
    notes text,
    created_at timestamptz not null default now(),

    constraint outlets_brand_check
        check (brand in ('fore', 'kopken', 'tomoro', 'starbuck')),
    constraint outlets_rating_check
        check (rating is null or rating between 0 and 5),
    constraint outlets_review_count_check
        check (review_count is null or review_count >= 0),
    constraint outlets_brand_name_key unique (brand, name)
);

