-- Batalkan seluruh transaksi jika data yang masuk tidak lengkap.
do $validation$
begin
    if (select count(*) from public.outlets) <> 344 then
        raise exception 'Jumlah outlet tidak sesuai: seharusnya 344, didapat %',
            (select count(*) from public.outlets);
    end if;

    if exists (
        with expected (brand, total) as (
            values
                ('fore', 46),
                ('kopken', 42),
                ('tomoro', 129),
                ('starbuck', 127)
        ),
        actual as (
            select brand, count(*)::integer as total
            from public.outlets
            group by brand
        )
        select 1
        from expected
        left join actual using (brand)
        where actual.total is distinct from expected.total
    ) then
        raise exception 'Jumlah outlet per brand tidak sesuai dengan file JSON';
    end if;
end
$validation$;

-- Data outlet boleh dibaca klien, tetapi tidak boleh diubah memakai anon key.
alter table public.outlets enable row level security;

create policy "outlets_public_read"
on public.outlets
for select
to anon, authenticated
using (true);

revoke all on table public.outlets from anon, authenticated;
grant select on table public.outlets to anon, authenticated;

commit;

-- Pemeriksaan setelah eksekusi:
select brand, count(*) as total
from public.outlets
group by brand
order by brand;
